export const sciencePhotoLessons=Object.fromEntries(Object.entries(scienceExplanationPhotos).map(([id,cards])=>[id,[...new Set(Object.values(cards))]]));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function photoForExplanation(lessonId,card,{subject='science',stage=0,view='lesson'}={}){if(subject!=='science'||stage!==0||view!=='lesson'||!Number.isInteger(card))return null;const id=scienceExplanationPhotos[lessonId]?.[card];return id?{id,...sciencePhotos[id]}:null;}
export function explanationPhoto(lessonId,card,context){const p=photoForExplanation(lessonId,card,context);if(!p)return '';return `<figure class="science-explanation-photo"><img src="${esc(p.file)}" width="${p.width}" height="${p.height}" alt="${esc(p.alt)}"><figcaption><p class="science-photo-observation"><strong>${esc(p.name)}.</strong> ${esc(p.inlineCaption)}</p><p class="science-photo-credit">${esc(p.kind)} · ${esc(p.author)} · <a href="${esc(p.licenceURL)}" target="_blank" rel="noopener">${esc(p.licence)}</a> · <a href="${esc(p.source)}" target="_blank" rel="noopener">Source</a></p></figcaption></figure>`;}
